    Identities keep the deterministic encounter order in which the
    segments' changes first name them. Each streak gets one fresh
    record with ordered keys ``type, identity, from, to, segments,
    added, removed, changed, changes``; ``from``/``to`` are the left
    window position of the streak's first segment and the right
    window position of its last, and ``changes`` keeps one isolated
    ``from, to, kind, before, after`` entry per segment. Records sort
    by total change count descending, then ``from`` and ``to``
    ascending, then the node, edge, gap grouping and identity
    encounter order. The complete set is built before the
    ``streak_limit`` cap is enforced, so an over-limit query raises
    :class:`ValueError` without returning partial records.
    """
    type_order = {"node": 0, "edge": 1, "gap": 2}
    # Key -> ordered list of (segment position, change) it appears in.
    per_identity: dict[
        tuple[str, object], list[tuple[int, dict[str, object]]]
    ] = {}
    encounter: dict[tuple[str, object], int] = {}
    next_encounter = 0
    for position, changes in enumerate(segment_changes):
        for change in changes:
            type_name = change["kind"].split("_", 1)[0]
            key = (type_name, change["identity"])
            if key not in encounter:
                encounter[key] = next_encounter
                next_encounter += 1
            per_identity.setdefault(key, []).append((position, change))

    records: list[dict[str, object]] = []
    for key, entries in per_identity.items():
        type_name, identity = key
        run: list[tuple[int, dict[str, object]]] = []

        def flush(run_entries: list[tuple[int, dict[str, object]]]) -> None:
            added_count = 0
            removed_count = 0
            changed_count = 0
            evidence: list[dict[str, object]] = []
            for run_position, change in run_entries:
                kind = change["kind"]
                if kind.endswith("_added"):
                    added_count += 1
                elif kind.endswith("_removed"):
                    removed_count += 1
                else:
                    changed_count += 1
                before = change["before"]
                after = change["after"]
                evidence.append(
                    {
                        "from": run_position,
                        "to": run_position + 1,
                        "kind": kind,
                        "before": (
                            None
                            if before is None
                            else BranchStore._copy_lifetime_record(before)
                        ),
                        "after": (
                            None
                            if after is None
                            else BranchStore._copy_lifetime_record(after)
                        ),
                    }
                )
            records.append(
                {
                    "type": type_name,
                    "identity": BranchStore._freeze_lifetime_value(
                        identity
                    ),
                    "from": run_entries[0][0],
                    "to": run_entries[-1][0] + 1,
                    "segments": len(run_entries),
                    "added": added_count,
                    "removed": removed_count,
                    "changed": changed_count,
                    "changes": tuple(evidence),
                }
            )

        for entry in entries:
            if run and entry[0] != run[-1][0] + 1:
                flush(run)
                run = []
            run.append(entry)
        if run:
            flush(run)

    records.sort(
        key=lambda record: (
            -(
                record["added"]
                + record["removed"]
                + record["changed"]
            ),
            record["from"],
            record["to"],
            type_order[record["type"]],
            encounter[(record["type"], record["identity"])],
        )
    )
    if len(records) > streak_limit_value:
        raise ValueError(
            f"lifetime churn streak limit exceeded: {len(records)} "
            f"streak records, limit is {streak_limit_value}"
        )

    total_added = 0
    total_removed = 0
    total_changed = 0
    for record in records:
        total_added += record["added"]
        total_removed += record["removed"]
        total_changed += record["changed"]
    return {
        "streaks": tuple(records),
        "totals": {
            "streaks": len(records),
            "identities": len(per_identity),
            "added": total_added,
            "removed": total_removed,
            "changed": total_changed,
        },
    }

@staticmethod
def _build_lifetime_changes(
    left_lifetimes: tuple[dict[str, object], ...],
    right_lifetimes: tuple[dict[str, object], ...],
) -> tuple[dict[str, object], ...]:
    """Compare two windows' lifetime records type by type, by identity.

    Records are grouped by nodes, then edges, then gaps; each group
    runs removed, added and changed. Removed and changed records
    follow the left window's identity order, added records the right
    window's, so the output is stable. An identity present in both
    windows changes when its first/last position, presence intervals
    or classification transitions differ; a completely equal pair is
    omitted. Every present side is copied again, so the change
    records share no object with either returned lifetime tuple.
    """
    changes: list[dict[str, object]] = []
    for type_name in ("node", "edge", "gap"):
        left_records = [
            record
            for record in left_lifetimes
            if record["type"] == type_name
        ]
        right_records = [
            record
            for record in right_lifetimes
            if record["type"] == type_name
        ]
        left_by_identity = {
            record["identity"]: record for record in left_records
        }
        right_by_identity = {
            record["identity"]: record for record in right_records
        }
        for record in left_records:
            if record["identity"] not in right_by_identity:
                changes.append(
                    {
                        "kind": f"{type_name}_removed",
                        "identity": BranchStore._freeze_lifetime_value(
                            record["identity"]
                        ),
                        "before": BranchStore._copy_lifetime_record(
                            record
                        ),
                        "after": None,
                    }
                )
        for record in right_records:
            if record["identity"] not in left_by_identity:
                changes.append(
                    {
                        "kind": f"{type_name}_added",
                        "identity": BranchStore._freeze_lifetime_value(
                            record["identity"]
                        ),
                        "before": None,
                        "after": BranchStore._copy_lifetime_record(
                            record
                        ),
                    }
                )
        for record in left_records:
            other = right_by_identity.get(record["identity"])
            if other is None:
                continue
            changed = (
                record["first_seen"] != other["first_seen"]
                or record["last_seen"] != other["last_seen"]
                or record["intervals"] != other["intervals"]
                or record["transitions"] != other["transitions"]
            )
            if changed:
                changes.append(
                    {
                        "kind": f"{type_name}_changed",
                        "identity": BranchStore._freeze_lifetime_value(
                            record["identity"]
                        ),
                        "before": BranchStore._copy_lifetime_record(
                            record
                        ),
                        "after": BranchStore._copy_lifetime_record(
                            other
                        ),
                    }
                )
    return tuple(changes)

def _cascade_slice_timeline_data(
    self,
    prepared: dict[str, object],
    index_values: list[int],
    causes: tuple[str, ...],
    direction: str,
    depth_value: int,
    node_limit_value: int,
    change_limit_value: int,
) -> tuple[tuple[dict[str, object], ...], tuple[dict[str, object], ...]]:
    """Build the frozen per-index snapshots and adjacent segments.

    Shared by :meth:`cascade_slice_timeline` and
    :meth:`cascade_slice_lifetimes` so both read the same selected
    snapshots and adjacent change segments from the one captured
    view. Every input and state check has already run; an empty
    index list selects nothing, an empty cause set yields an empty
    slice per position, and the per-position node cap and the total
    change cap are enforced before any result is assembled.
    """
    if not index_values:
        # Every input and state check is done; no position is selected.
        return (), ()

